# TODO automatic interface discovery

INTERFACES = [
    RootInterface,

    # /
    ChannelInterface,
    StatusInterface,

    # /library
    LibraryInterface,
    LibraryMetadataInterface,
    SectionInterface,

    # /:
    PreferencesInterface,
    TimelineInterface,

    # /:/plugins
    PluginInterface,
    PluginPreferencesInterface
]


def get_interfaces():
    for interface in INTERFACES:
        if interface.path:
            path = interface.path.strip('/')
        else:
            path = ''

        if path:
            path = path.split('/')
        else:
            path = []

        yield path, interface


def construct_map(client, d=None, interfaces=None):
    if d is None:
        d = {}

    if interfaces is None:
        interfaces = get_interfaces()

    for path, interface in interfaces:
        if len(path) > 0:
            key = path.pop(0)
        else:
            key = None

        if key == '*':
            key = None

        if len(path) == 0:
            d[key] = interface(client)
            continue

        value = d.get(key, {})

        if type(value) is not dict:
            value = {None: value}

        construct_map(client, value, [(path, interface)])

        d[key] = value

    return d

