static void make_dagnode (dagnode_t *d, s3wid_t wid, int32 sf, int32 ef)
{
    d->wid = wid;
    d->seqid = 0;
    d->sf = sf;
    d->fef = ef;
    d->lef = d->fef;
    d->reachable = 0;
    d->next = NULL;
    d->predlist = NULL;
