                ultimaMensagem.MostrarMensagensNovas = 
                    mensagem?.ContatoDestinatarioId == filtro.ContatoId && ultimaMensagem.QtdMensagensNovas > 0;

                if (amigo != null) return;

                ultimaMensagem.EhAmigo = false;
